const shows = $input.all().map(item => item.json);

// ------------------------------------------
// Clean data - keep only essential fields
// ------------------------------------------
const cleanedShows = shows.filter(show => {

  const rating = show.rating?.average;
  const premiered = show.premiered;

  // Rating is required because it is the target
  if (rating === null || rating === undefined) {
    return false;
  }

  // Valid premiere date
  if (!premiered) {
    return false;
  }

  // Premiere date: 1990-01-01 → 2026-05-31
  if (
    premiered < "1990-01-01" ||
    premiered > "2026-05-31"
  ) {
    return false;
  }

  // Valid show identity
  if (!show.id || !show.name) {
    return false;
  }

  return true;
});

// ------------------------------------------
// Remove duplicate shows by ID
// ------------------------------------------
const uniqueShows = [];
const seenIds = new Set();

for (const show of cleanedShows) {

  if (!seenIds.has(show.id)) {
    seenIds.add(show.id);
    uniqueShows.push(show);
  }

}

// ------------------------------------------
// Keep maximum 30,000 real shows
// ------------------------------------------
const finalShows = uniqueShows
  .sort((a, b) => a.id - b.id)
  .slice(0, 30000);

// ------------------------------------------
// Convert shows into ML-style features
// ------------------------------------------
const output = finalShows.map(show => {

  const rating = Number(show.rating.average);
  const runtime =
    show.runtime !== null && show.runtime !== undefined
      ? Number(show.runtime)
      : null;

  const weight = Number(show.weight || 0);

  // Premiere year
  const premiereYear = show.premiered
    ? Number(show.premiered.substring(0, 4))
    : null;

  // Genres
  const genres = Array.isArray(show.genres)
    ? show.genres
    : [];

  // Genre features
  const genreDrama =
    genres.includes("Drama") ? 1 : 0;

  const genreComedy =
    genres.includes("Comedy") ? 1 : 0;

  const genreCrime =
    genres.includes("Crime") ? 1 : 0;

  const genreAction =
    genres.includes("Action") ? 1 : 0;

  const genreAdventure =
    genres.includes("Adventure") ? 1 : 0;

  const genreRomance =
    genres.includes("Romance") ? 1 : 0;

  const genreThriller =
    genres.includes("Thriller") ? 1 : 0;

  const genreMystery =
    genres.includes("Mystery") ? 1 : 0;

  const genreFamily =
    genres.includes("Family") ? 1 : 0;

  const genreScienceFiction =
    genres.includes("Science-Fiction") ? 1 : 0;

  // ----------------------------------------
  // High / Low Rating Classification
  // Same rule as Python
  // Rating >= 5 = High Rated
  // Rating < 5 = Low Rated
  // ----------------------------------------
  const label = rating >= 5 ? 1 : 0;

  const classification =
    label === 1
      ? "High Rated"
      : "Low Rated";

  return {
    json: {

      id: show.id,
      name: show.name,
      genres: genres,
      runtime: runtime,
      premiered: show.premiered,
      rating: rating,
      weight: weight,

      language: show.language || null,
      type: show.type || null,
      status: show.status || null,

      network: show.network?.name || null,
      country: show.country?.name || null,

      // ML features
      premiere_year: premiereYear,

      genre_drama: genreDrama,
      genre_comedy: genreComedy,
      genre_crime: genreCrime,
      genre_action: genreAction,
      genre_adventure: genreAdventure,
      genre_romance: genreRomance,
      genre_thriller: genreThriller,
      genre_mystery: genreMystery,
      genre_family: genreFamily,
      genre_science_fiction: genreScienceFiction,

      // Target
      label: label,
      classification: classification
    }
  };

});

// ------------------------------------------
// Final information
// ------------------------------------------
console.log("Original records:", shows.length);
console.log("After cleaning:", cleanedShows.length);
console.log("Unique shows:", uniqueShows.length);
console.log("Final shows:", output.length);

// ------------------------------------------
// Return data
// ------------------------------------------
return output;
